def calculate_final_price(initial_total, codes, discounts):
    current_total = initial_total
    unaccepted_codes = []

    for c in codes:
        try:
            value = discounts[c]
            current_total = current_total - value
        except KeyError:
            unaccepted_codes.append(c)

    result_data = {
        'total': current_total,
        'rejected': unaccepted_codes
    }

    return result_data
